def term_path(slug): return f"term-{slug}.html"

def term_page(t):
    slug, name, cat, one, paras, rel_paths = t
    path = term_path(slug)
    title = f"{name}이란 — 뜻과 확인 방법 | 부동산 용어 사전"
    desc = f"{name}: {one}. " + re.sub(r"<[^>]+>", "", paras[0])[:110] + "…"
    rel_src = [x for x in TOOLS if x[0] in rel_paths] + [(f, n, "", "", "", d) for (f, n, _t, _d, d) in TABLES + FORMS if f in rel_paths]
    rel = "".join(f'<a class="tool-card" href="{f}"><p class="t">{n}</p><p class="d">{d}</p></a>' for (f, n, _t, _d, _c, d) in rel_src)
    # 같은 분류의 다른 용어
    others = [x for x in TERMS if x[2] == cat and x[0] != slug][:6]
    more = "".join(f'<li><a href="{term_path(s)}">{n}</a> <span class="muted">— {o}</span></li>' for (s, n, _c, o, _p, _r) in others)
    body = "\n".join("        " + p for p in paras)
    main = f'''    <article class="article">
      <section class="hero">
        <p class="eyebrow">Glossary</p>
        <div class="term-head"><h1>{name}</h1><span class="term-cat">{cat}</span></div>
        <p class="lead">{one}</p>
        <p class="meta"><a href="glossary.html">부동산 용어 사전</a> · {TODAY.replace("-", ".")} · 참고용 설명이며 법률·세무 자문이 아닙니다</p>
      </section>
      <section class="card">
        <div class="prose">
{body}
        </div>
      </section>{INLINE_AD}
      <section class="card related" aria-labelledby="rel-title">
        <h2 id="rel-title">관련 계산기·자료</h2>
        <div class="tool-grid">{rel}</div>
      </section>
      <section class="card">
        <h2>같은 분류의 용어</h2>
        <ul class="prose" style="margin:0;padding-left:18px">{more}</ul>
        <p class="hint" style="margin-top:12px"><a href="glossary.html">← 용어 사전 전체</a></p>
      </section>
    </article>'''
    ld = jsonld({"@context": "https://schema.org", "@type": "DefinedTerm", "name": name, "description": one, "url": BASE + path, "inLanguage": "ko-KR",
                 "inDefinedTermSet": {"@type": "DefinedTermSet", "name": "전국부동산계산기 부동산 용어 사전", "url": BASE + "glossary.html"}})
    return page(title, desc, path, main, extra_head=ld + article_ld(title, desc, path) + breadcrumb_ld(name, path), og_type="article",
                disclaimer="본 설명은 참고용이며 금융·세무·법률 자문이 아닙니다. 법령은 개정될 수 있습니다.")

def glossary_index():
    f, name, title, desc = GLOSSARY_INDEX
    cats = []
    for c in ["계약·권리", "등기", "세금", "대출", "청약·분양", "면적·거래"]:
        items = "".join(f'<a class="tool-card" href="{term_path(s)}"><p class="t">{n}</p><p class="d">{o}</p></a>' for (s, n, cc, o, _p, _r) in TERMS if cc == c)
        cats.append(f'''
    <section class="hub-cat" id="cat-{len(cats)}" aria-labelledby="h-{len(cats)}">
      <h2 id="h-{len(cats)}">{c}</h2>
      <div class="tool-grid">{items}</div>
    </section>''')
    idx = "".join(f'<a href="#cat-{i}">{c}</a>' for i, c in enumerate(["계약·권리", "등기", "세금", "대출", "청약·분양", "면적·거래"]))
    main = f'''    <section class="hero">
      <p class="eyebrow">Glossary</p>
      <h1>부동산 용어 사전</h1>
      <p class="hero-sub">계약서와 등기부, 세금 고지서에 나오는 말을 한 페이지에 하나씩</p>
      <p class="hero-body">{len(TERMS)}개 용어를 뜻, 왜 중요한지, 어디서 확인하는지 순서로 설명하고 관련 계산기로 연결합니다. 법령은 바뀔 수 있으니 기준일을 확인하세요.</p>
    </section>
    <div class="alpha-index">{idx}</div>{"".join(cats[:3])}{INLINE_AD}{"".join(cats[3:])}'''
    ld = jsonld({"@context": "https://schema.org", "@type": "DefinedTermSet", "name": "전국부동산계산기 부동산 용어 사전", "url": BASE + f, "inLanguage": "ko-KR",
                 "hasDefinedTerm": [{"@type": "DefinedTerm", "name": n, "url": BASE + term_path(s)} for (s, n, _c, _o, _p, _r) in TERMS]})
    return page(title, desc, f, main, extra_head=ld + breadcrumb_ld(name, f))
